INSERT INTO destinasi_wisata VALUES (1,'Agrowisata Kalisentul',4,'Kalibawang','Banjarharjo','Kulon Progo','Tourist attraction','Agrowisata Kalisentul merupakan destinasi wisata yang mengangkat potensi pertanian dan suasana alam di kawasan Kalibawang. Destinasi ini berpotensi menawarkan pengalaman wisata berbasis alam dan kegiatan pertanian lokal bagi pengunjung yang ingin mengenal kehidupan perdesaan.',5.0,7,'Rp0',NULL,NULL,'08.00–18.00; data akhir pekan menunjukkan 24 jam*','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6742883,110.2324447','8','',ST_SetSRID(ST_MakePoint(110.2324447,-7.6742883),4326));
INSERT INTO destinasi_wisata VALUES (2,'AGROWISATA KRISAN GERBOSARI',4,'Samigaluh','Gerbosari','Kulon Progo','Tourist attraction','Agrowisata Krisan Gerbosari merupakan destinasi wisata pertanian yang menawarkan keindahan bunga krisan yang dibudidayakan oleh masyarakat setempat.',4.4,407,'Rp5.000','Rp80.000','Rp5.000-RP25.000','08.00–23.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',5000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6779295,110.1728034','4','',ST_SetSRID(ST_MakePoint(110.1728034,-7.6779295),4326));
INSERT INTO destinasi_wisata VALUES (3,'Desa Wisata Nglinggo',4,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction, Park','Desa Wisata Nglinggo merupakan desa wisata di kawasan Perbukitan Menoreh yang memadukan potensi alam, budaya, dan kehidupan masyarakat lokal. Daya tariknya meliputi perkebunan teh, wisata edukasi, kegiatan off-road, kesenian tradisional Lengger Tapeng, serta berbagai pilihan homestay dan aktivitas wisata.',4.4,689,'Rp5.000 - Rp15.000','Rp100.000 - Rp350.000','Rp5.000 - Rp.35.000','09.00–17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',10000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6476680,110.1418780','21','',ST_SetSRID(ST_MakePoint(110.1418780,-7.6476680),4326));
INSERT INTO destinasi_wisata VALUES (4,'Gubuk jamur (Jamur Tiram & Kuping)',4,'Kalibawang','Banjarharjo','Kulon Progo','Tourist attraction','Gubuk Jamur merupakan destinasi yang berkaitan dengan budidaya jamur tiram dan jamur kuping. Tempat ini berpotensi menjadi wisata edukasi pertanian yang memperkenalkan proses budidaya jamur serta pemanfaatannya sebagai produk pangan.',5.0,5,'Rp0',NULL,'Rp3.000 - Rp85.000','07.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6950906,110.2468443','6','',ST_SetSRID(ST_MakePoint(110.2468443,-7.6950906),4326));
INSERT INTO destinasi_wisata VALUES (5,'Kebun Teh Nglinggo',4,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction','Kebun Teh Nglinggo merupakan kawasan perkebunan teh di Perbukitan Menoreh yang menawarkan hamparan tanaman teh dengan udara sejuk dan panorama perbukitan. Pengunjung dapat berjalan menyusuri area perkebunan sambil menikmati suasana alam dan pemandangan dari dataran tinggi.',4.5,4362,'Rp5.000 - Rp15.000',NULL,NULL,'07.00–18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',10000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6459518,110.1436743','2','Titik batas: RBI menempatkan di Salaman (selisih 68 m dari batas); mengikuti catatan tim',ST_SetSRID(ST_MakePoint(110.1436743,-7.6459518),4326));
INSERT INTO destinasi_wisata VALUES (6,'Kebun Teh Tritis',4,'Samigaluh','Ngargosari','Kulon Progo','Traditional teahouse, Tourist attraction','Kebun Teh Tritis menawarkan pemandangan hamparan tanaman teh di kawasan perbukitan Menoreh. Suasana hijau, udara sejuk, dan lanskap perkebunan menjadikannya tempat yang menarik untuk menikmati alam serta mengambil foto.',4.3,264,'Rp5.000 - Rp10.000',NULL,'Rp25.000 - Rp100.000','24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',7500,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6506933,110.1492634','1','',ST_SetSRID(ST_MakePoint(110.1492634,-7.6506933),4326));
INSERT INTO destinasi_wisata VALUES (7,'NGORI KEBONHARJO',4,'Samigaluh','Kebonharjo','Kulon Progo','Park','Ngori Kebonharjo merupakan destinasi wisata di kawasan perdesaan Kulon Progo yang menawarkan suasana alam dan lingkungan hijau. Tempat ini dapat menjadi pilihan untuk bersantai sekaligus menikmati suasana pedesaan yang jauh dari keramaian perkotaan.',4.4,42,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6957101,110.1374007','5','',ST_SetSRID(ST_MakePoint(110.1374007,-7.6957101),4326));
INSERT INTO destinasi_wisata VALUES (8,'PROGO BANASRI FARM',4,'Kalibawang','Banjarasri','Kulon Progo','Tourist attraction','Progo Banasri Farm merupakan destinasi berbasis pertanian yang berada di kawasan Banjarasri, Kalibawang. Tempat ini dapat diperkenalkan sebagai pilihan untuk mengenal potensi usaha pertanian lokal dan suasana lingkungan perdesaan di sekitar kawasan Sungai Progo.',5.0,23,'Rp0',NULL,NULL,'09.00–17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6993570,110.2380821','7','',ST_SetSRID(ST_MakePoint(110.2380821,-7.6993570),4326));
INSERT INTO destinasi_wisata VALUES (9,'Sawah Nglorok',4,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction','Sawah Nglorok merupakan kawasan persawahan yang menawarkan pemandangan lanskap pedesaan di wilayah Samigaluh. Hamparan lahan pertanian dan latar perbukitan Menoreh menjadikannya tempat yang menarik untuk menikmati suasana pedesaan dan fotografi lanskap.',NULL,NULL,'Rp0',NULL,NULL,'08.00–23.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6732440,110.1411900','3','Belum ada rating/ulasan di Google Maps',ST_SetSRID(ST_MakePoint(110.1411900,-7.6732440),4326));
INSERT INTO destinasi_wisata VALUES (10,'dolaNdeso Boro',5,'Kalibawang','Banjarasri','Kulon Progo','National reserve, Tourist attraction','dolaNdeso Boro merupakan destinasi wisata berbasis alam dan aktivitas luar ruang di kawasan Boro, Kulon Progo. Tempat ini dikenal sebagai pilihan untuk rekreasi, kegiatan kelompok, dan pengalaman wisata yang memadukan suasana pedesaan dengan aktivitas petualangan.',4.4,2717,'Rp5.000','RP65.000 - Rp255.000',NULL,'08.00–16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',5000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6982391,110.2221990','16','',ST_SetSRID(ST_MakePoint(110.2221990,-7.6982391),4326));
INSERT INTO destinasi_wisata VALUES (11,'GLAMPING MENOREH',5,'Samigaluh','Pagerharjo','Kulon Progo','Campground','Glamping Menoreh menawarkan pengalaman menginap di alam terbuka dengan konsep glamorous camping. Destinasi ini memadukan suasana alam perbukitan dengan fasilitas menginap yang lebih nyaman, sehingga cocok untuk beristirahat dan menikmati suasana alam.',4.4,253,'Rp5.000 - Rp10.000','Rp500.000 - Rp1.500.000/tenda',NULL,'Jam Check-in: Pukul 14.00 – 18.00 WIB (atau hingga pukul 23.00 WIB tergantung kebijakan/konfirmasi pihak pengelola)','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',500000,5,'paket menginap (batas bawah)',FALSE,TRUE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6564931,110.1401295','10','',ST_SetSRID(ST_MakePoint(110.1401295,-7.6564931),4326));
INSERT INTO destinasi_wisata VALUES (12,'Menoreh Rock Cabin',5,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction, Camping cabin','Menoreh Rock Cabin merupakan destinasi penginapan bernuansa alam di kawasan Perbukitan Menoreh. Konsep kabin dan lingkungan perbukitan memberikan pengalaman menginap yang dekat dengan alam, cocok untuk bersantai dan menikmati suasana kawasan Menoreh.',4.8,46,'Rp25.000','Rp500.000 - Rp750.000',NULL,'24 jam',NULL,500000,5,'paket menginap (batas bawah)',FALSE,TRUE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6658125,110.1328125','11','',ST_SetSRID(ST_MakePoint(110.1328125,-7.6658125),4326));
INSERT INTO destinasi_wisata VALUES (13,'PROBOSIWI RESORT',5,'Girimulyo','Giripurwo','Kulon Progo','Hotel','Probosiwi Resort merupakan destinasi untuk beristirahat dan menikmati suasana alam di kawasan Kulon Progo. Tempat ini dapat menjadi pilihan bagi wisatawan yang ingin bersantai sekaligus menjelajahi berbagai objek wisata di sekitarnya.',4.9,280,'Rp0','Rp350.000 - Rp600.000',NULL,'Waktu Check-in (Masuk): Pukul 14.00 WIB','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',350000,5,'paket menginap (batas bawah)',FALSE,TRUE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7590331,110.1650925','12','',ST_SetSRID(ST_MakePoint(110.1650925,-7.7590331),4326));
INSERT INTO destinasi_wisata VALUES (14,'Rest Area Segitik',5,'Samigaluh','Pagerharjo','Kulon Progo','Rest stop','Rest Area Segitik menjadi tempat singgah bagi wisatawan yang menjelajahi kawasan perbukitan Kulon Progo. Tempat ini dapat dimanfaatkan untuk beristirahat sejenak sembari menikmati suasana sekitar sebelum melanjutkan perjalanan ke destinasi wisata lainnya.',4.3,37,'Rp0',NULL,NULL,'07.00–17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6611238,110.1433749','9','',ST_SetSRID(ST_MakePoint(110.1433749,-7.6611238),4326));
INSERT INTO destinasi_wisata VALUES (15,'Shafira Garden',5,'Kalibawang','Banjarasri','Kulon Progo','Park, Caterer','Shafira Garden merupakan destinasi wisata bernuansa taman yang menawarkan suasana terbuka untuk bersantai dan berkumpul. Tempat ini dapat menjadi alternatif kunjungan bagi wisatawan yang ingin menikmati waktu luang dalam suasana yang nyaman.',4.6,27,'Rp0',NULL,'Rp5.000 - Rp45.000',NULL,NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7072221,110.2408636','14','',ST_SetSRID(ST_MakePoint(110.2408636,-7.7072221),4326));
INSERT INTO destinasi_wisata VALUES (16,'Tubing & Black Hole Banjarasri',5,'Kalibawang','Banjarasri','Kulon Progo','Tourist attraction','Tubing & Black Hole Banjarasri menawarkan pengalaman wisata petualangan berbasis alam dengan aktivitas menyusuri aliran sungai menggunakan ban pelampung. Destinasi ini cocok bagi pencinta kegiatan luar ruang yang ingin menikmati sensasi petualangan di tengah lingkungan alami.',5.0,2,'Rp0',NULL,NULL,'08.00–15.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6987921,110.2213183','15','',ST_SetSRID(ST_MakePoint(110.2213183,-7.6987921),4326));
INSERT INTO destinasi_wisata VALUES (17,'Candi Pringtali',3,'Samigaluh','Kebonharjo','Kulon Progo','Historical landmark, Tourist attraction','Candi Pringtali merupakan situs budaya yang menjadi bagian dari kekayaan sejarah dan warisan lokal di Kulon Progo. Keberadaannya menarik bagi pengunjung yang ingin mengenal peninggalan masa lalu serta nilai sejarah dan budaya masyarakat setempat.',4.4,83,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7106853,110.1602980','80','',ST_SetSRID(ST_MakePoint(110.1602980,-7.7106853),4326));
INSERT INTO destinasi_wisata VALUES (18,'Desa Wisata Banjaroya Jogja',3,'Kalibawang','Banjaroyo','Kulon Progo','Tourist attraction','Desa Wisata Banjaroya merupakan destinasi wisata berbasis masyarakat di Kapanewon Kalibawang, Kulon Progo. Kawasan ini menawarkan pengalaman wisata pedesaan dengan potensi alam, budaya lokal, serta kehidupan masyarakat yang khas.',5.0,16,'Rp0','Rp40.000 – Rp200.000','Rp15.000 - 20.000/pax','07.00–16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6522479,110.2558633','19','',ST_SetSRID(ST_MakePoint(110.2558633,-7.6522479),4326));
INSERT INTO destinasi_wisata VALUES (19,'Gua Maria Lawangsih',3,'Girimulyo','Purwosari','Kulon Progo','Place of worship, Tourist attraction','Gua Maria Lawangsih merupakan tempat ziarah umat Katolik yang berada di kawasan perbukitan Kulon Progo. Suasana gua yang tenang dan lingkungan alam yang asri menjadikannya tempat untuk berdoa, bermeditasi, dan melakukan refleksi spiritual.',4.8,541,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7211213,110.1480054','82','',ST_SetSRID(ST_MakePoint(110.1480054,-7.7211213),4326));
INSERT INTO destinasi_wisata VALUES (20,'Gua Maria Sendangsono',3,'Kalibawang','Banjaroyo','Kulon Progo','Shrine, Pilgrimage place, Place of worship, Tourist attraction','Gua Maria Sendangsono merupakan tempat ziarah Katolik yang terkenal di kawasan Kalibawang, Kulon Progo. Dikelilingi pepohonan dan lingkungan yang asri, tempat ini menjadi tujuan umat untuk berdoa, berziarah, serta mengenang sejarah perkembangan Katolik di wilayah tersebut.',4.8,4179,'Rp0','Rp150.000','Rp15.000 - Rp20.000','09.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6679857,110.2255368','85','',ST_SetSRID(ST_MakePoint(110.2255368,-7.6679857),4326));
INSERT INTO destinasi_wisata VALUES (21,'Gua Maria Watu Blencong (Dusun Boro Suci)',3,'Kalibawang','Banjarasri','Kulon Progo','Shrine, Tourist attraction','Gua Maria Watu Blencong, Borosuci merupakan tempat ziarah umat Katolik yang digunakan untuk berdoa dan melakukan kegiatan rohani. Berada di lingkungan pedesaan, tempat ini menawarkan suasana yang tenang bagi peziarah yang ingin melakukan refleksi spiritual.',4.67,190,'Rp0',NULL,NULL,'24 Jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6843436,110.2169170','83; 24','Gabungan 2 entri duplikat (asumsi, jarak 127 m); konfirmasi saat ground check',ST_SetSRID(ST_MakePoint(110.2169170,-7.6843436),4326));
INSERT INTO destinasi_wisata VALUES (22,'Gua Maria Welas Asih (Saint Mary''s Grotto Welas Asih)',3,'Kalibawang','Banjaroyo','Kulon Progo','Place of worship','Gua Maria Welas Asih merupakan destinasi wisata religi Katolik yang menjadi tempat doa dan ziarah bagi umat. Suasananya mendukung kegiatan perenungan dan ibadah, sekaligus menjadi bagian dari perjalanan wisata religi di kawasan sekitarnya.',4.6,97,'Rp0',NULL,NULL,NULL,NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6507059,110.2164534','18','',ST_SetSRID(ST_MakePoint(110.2164534,-7.6507059),4326));
INSERT INTO destinasi_wisata VALUES (23,'Makam Nyi Ageng Serang',3,'Kalibawang','Banjarharjo','Kulon Progo','Shrine','Makam Nyi Ageng Serang merupakan situs sejarah yang berkaitan dengan tokoh pahlawan nasional Nyi Ageng Serang, yang berperan dalam perjuangan melawan kolonialisme. Tempat ini menjadi tujuan wisata sejarah dan ziarah bagi pengunjung yang ingin mengenal perjuangan serta warisan sejarah Indonesia.',4.6,21,'Rp0',NULL,NULL,'09.00–22.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6866261,110.2408263','86','',ST_SetSRID(ST_MakePoint(110.2408263,-7.6866261),4326));
INSERT INTO destinasi_wisata VALUES (24,'Our Lady of Lourdes Catholic Church, Promasan',3,'Kalibawang','Banjaroyo','Kulon Progo','Catholic church, Tourist attraction','Our Lady of Lourdes Catholic Church, Promasan merupakan gereja Katolik di kawasan Promasan yang menjadi tempat ibadah dan kegiatan rohani umat. Lingkungannya yang tenang juga menjadikannya bagian dari tujuan wisata religi di kawasan perbukitan Kulon Progo.',4.8,283,'Rp0',NULL,NULL,'Senin – Kamis: 07:00 – 14:30, Jumat: Libur / Tutup, Sabtu: 07:00 – 14:00, Minggu: 07:00 – 13:00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6661845,110.2346167','76','',ST_SetSRID(ST_MakePoint(110.2346167,-7.6661845),4326));
INSERT INTO destinasi_wisata VALUES (25,'Air Terjun Kembang Soka',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction, Park','Air Terjun Kembang Soka merupakan destinasi wisata air terjun di Kulon Progo yang menawarkan aliran air jernih dengan perpaduan warna kolam alami dan bebatuan. Lingkungan yang hijau menjadikannya tempat menarik untuk menikmati pemandangan dan kesegaran alam.',4.7,1424,'Rp11.000',NULL,NULL,'08.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',11000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7664251,110.1175615','48; 49','Gabungan 2 entri duplikat (asumsi, jarak 56 m); konfirmasi saat ground check',ST_SetSRID(ST_MakePoint(110.1175615,-7.7664251),4326));
INSERT INTO destinasi_wisata VALUES (26,'Air Terjun Sidoharjo',1,'Samigaluh','Sidoharjo','Kulon Progo','Tourist attraction','Air Terjun Sidoharjo merupakan salah satu destinasi wisata alam di kawasan Samigaluh, Kulon Progo, yang dikenal dengan aliran air terjun tinggi dan lingkungan hijau. Pemandangan alamnya menjadi daya tarik bagi pengunjung yang ingin menikmati keindahan air terjun dan suasana sejuk.',4.5,831,'Rp0 - Rp5.000',NULL,NULL,'24 jam. Waktu Kunjungan Terbaik: Pagi hari (sekitar pukul 06.00 – 09.00)',NULL,2500,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6699738,110.2019759','38','',ST_SetSRID(ST_MakePoint(110.2019759,-7.6699738),4326));
INSERT INTO destinasi_wisata VALUES (27,'AIR TERJUN SILUOK',1,'Samigaluh','Sidoharjo','Kulon Progo','Tourist attraction','Air Terjun Siluok merupakan destinasi wisata alam yang menyuguhkan aliran air di tengah lingkungan yang masih alami. Tempat ini cocok bagi wisatawan yang ingin menikmati suasana tenang dan menjelajahi keindahan alam Kulon Progo.',4.6,30,'Rp0',NULL,NULL,'06.00 – 17.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6638748,110.1877850','39','',ST_SetSRID(ST_MakePoint(110.1877850,-7.6638748),4326));
INSERT INTO destinasi_wisata VALUES (28,'Bendung Khayangan Adventure Park',1,'Girimulyo','Pendoworejo','Kulon Progo','Tourist attraction','Bendung Khayangan Adventure Park merupakan destinasi wisata yang memadukan lingkungan sungai dan bendungan dengan aktivitas rekreasi luar ruang. Kawasan ini cocok untuk menikmati panorama alam, bersantai, dan melakukan kegiatan wisata bersama keluarga atau kelompok.',4.4,612,'Rp0',NULL,NULL,'24 jam.','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7450593,110.1806758','55','',ST_SetSRID(ST_MakePoint(110.1806758,-7.7450593),4326));
INSERT INTO destinasi_wisata VALUES (29,'Bukit Sebantung (Kedung Pedut Jilid II)',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction','Bukit Sebantung (Kedung Pedut Jilid II) merupakan destinasi wisata alam di kawasan perbukitan Kulon Progo yang menawarkan pemandangan hijau dan suasana alami. Tempat ini menjadi pilihan bagi wisatawan yang ingin menikmati panorama alam dan beraktivitas di luar ruangan.',4.4,35,'Rp0',NULL,NULL,'08.00 – 15.30 / 16.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7722270,110.1212440','44','',ST_SetSRID(ST_MakePoint(110.1212440,-7.7722270),4326));
INSERT INTO destinasi_wisata VALUES (30,'Curug Glimpang',1,'Girimulyo','Purwosari','Kulon Progo','Tourist attraction','Curug Glimpang merupakan destinasi wisata air terjun yang menawarkan suasana alami dengan aliran air dan lingkungan hijau di sekitarnya. Destinasi ini dapat menjadi pilihan bagi wisatawan yang ingin menikmati keindahan alam dan suasana yang lebih tenang.',4.2,52,'Rp10.000','Rp50.000',NULL,'08.00–16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',10000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7084829,110.1382194','27','',ST_SetSRID(ST_MakePoint(110.1382194,-7.7084829),4326));
INSERT INTO destinasi_wisata VALUES (31,'Desa Wisata Jatimulyo - Kulon Progo',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction, Education center','Desa Wisata Jatimulyo merupakan destinasi wisata berbasis alam dan masyarakat di Kecamatan Girimulyo, Kulon Progo. Kawasan ini memiliki potensi wisata berupa air terjun, lingkungan hutan yang asri, serta keanekaragaman hayati yang menarik untuk kegiatan rekreasi dan ekowisata.',4.2,82,'Rp3.000','Rp10.000–Rp1.500.000','Rp10.000–Rp350.000','08.00–15.00 pada akhir pekan; 10.00–15.00 pada hari kerja','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',3000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7526214,110.1307636','23','',ST_SetSRID(ST_MakePoint(110.1307636,-7.7526214),4326));
INSERT INTO destinasi_wisata VALUES (32,'Desa Wisata Widosari (Desa Wisata Widosari Jogja)',1,'Samigaluh','Ngargosari','Kulon Progo','Tourist attraction','Desa Wisata Widosari merupakan desa wisata di kawasan Samigaluh yang mengandalkan potensi alam dan kehidupan pedesaan sebagai daya tarik utama. Kawasan ini juga menjadi akses menuju berbagai destinasi perbukitan, termasuk Puncak Widosari, serta menawarkan pengalaman wisata berbasis masyarakat.',4.8,61,'Rp15.000','Rp10.000–Rp175.000/orang','Rp5.000 - Rp.25.000','08.00–16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',15000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6615060,110.1542691','22','',ST_SetSRID(ST_MakePoint(110.1542691,-7.6615060),4326));
INSERT INTO destinasi_wisata VALUES (33,'Ekowisata Sungai Mudal',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction, Park, Water park','Sungai Mudal di Kecamatan Girimulyo, Kabupaten Kulon Progo, merupakan kawasan aliran sungai dengan sumber mata air alami dan lingkungan yang asri. Kejernihan air serta vegetasi di sekitarnya menjadikan kawasan ini menarik untuk rekreasi dan menikmati suasana alam.',4.71,10360,'Rp10.000','Rp30.000 - Rp95.000','Rp5.000 - Rp35.000','08.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',10000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7628166,110.1161247','46; 47','Gabungan 2 entri duplikat (asumsi, jarak 120 m); konfirmasi saat ground check',ST_SetSRID(ST_MakePoint(110.1161247,-7.7628166),4326));
INSERT INTO destinasi_wisata VALUES (34,'Embung Sidoharjo /Canggal',1,'Samigaluh','Sidoharjo','Kulon Progo','Water park','Embung Sidoharjo atau Embung Canggal merupakan tampungan air yang dikelilingi lanskap perdesaan dan perbukitan di wilayah Sidoharjo, Kulon Progo. Selain berfungsi sebagai sumber air, kawasan ini berpotensi menjadi tempat untuk menikmati pemandangan dan suasana alam.',4.6,341,'Rp0',NULL,NULL,'08.00 – 17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6747110,110.2017884','57','',ST_SetSRID(ST_MakePoint(110.2017884,-7.6747110),4326));
INSERT INTO destinasi_wisata VALUES (35,'Gardu Pandang Tanggulangsi',1,'Samigaluh','Gerbosari','Kulon Progo','Tourist attraction','Gardu Pandang Tanggulangsi merupakan tempat untuk menikmati panorama alam dari ketinggian di kawasan perbukitan Kulon Progo. Lokasi ini cocok untuk bersantai, mengamati bentang alam sekitar, dan mengambil foto pemandangan.',4.1,105,'Rp0',NULL,NULL,NULL,NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6815119,110.1772274','40','',ST_SetSRID(ST_MakePoint(110.1772274,-7.6815119),4326));
INSERT INTO destinasi_wisata VALUES (36,'Goa Kiskendo',1,'Girimulyo','Jatimulyo','Kulon Progo','Alam','Goa Kiskendo merupakan destinasi wisata alam dan budaya yang terletak di Kecamatan Girimulyo, Kabupaten Kulon Progo, Yogyakarta. Gua ini memiliki formasi batuan alami serta nilai legenda yang berkaitan dengan kisah Ramayana, sehingga menarik bagi wisatawan yang ingin menjelajahi keindahan gua sekaligus mengenal cerita dan budaya lokal.',4.3,2180,'Rp10.000','Rp375.000 - Rp750.000',NULL,'09.00 – 17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',10000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7471682,110.1314505','64','',ST_SetSRID(ST_MakePoint(110.1314505,-7.7471682),4326));
INSERT INTO destinasi_wisata VALUES (37,'Goa Sriti',1,'Samigaluh','Purwoharjo','Kulon Progo','Tourist attraction','Goa Sriti merupakan destinasi wisata gua yang menawarkan pengalaman menjelajahi bentang alam dan formasi alami di dalam gua. Tempat ini menarik bagi pengunjung yang ingin mengenal keunikan lingkungan gua serta potensi wisata alam setempat.',4.3,90,'Rp3.000',NULL,NULL,'09.00–17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',3000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7035962,110.2031232','41','',ST_SetSRID(ST_MakePoint(110.2031232,-7.7035962),4326));
INSERT INTO destinasi_wisata VALUES (38,'Grojogan Sewu Waterfall',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction','Grojogan Sewu Waterfall merupakan destinasi wisata air terjun yang menyuguhkan aliran air di tengah lingkungan alami dan pepohonan hijau. Tempat ini menawarkan suasana yang menyegarkan bagi pengunjung yang ingin menikmati keindahan alam.',4.2,358,'Rp3.000 - Rp4.000',NULL,NULL,'08.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',3500,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7519624,110.1358235','50','',ST_SetSRID(ST_MakePoint(110.1358235,-7.7519624),4326));
INSERT INTO destinasi_wisata VALUES (39,'Gunung kukusan',1,'Samigaluh','Pagerharjo','Kulon Progo','Hiking area','Gunung Kukusan merupakan destinasi wisata perbukitan di kawasan Menoreh yang dikenal dengan panorama alam dari area puncaknya. Pengunjung dapat menikmati lanskap perbukitan dan suasana alam yang sesuai untuk kegiatan trekking ringan serta fotografi, bergantung pada kondisi jalur.',NULL,NULL,'Rp5.000','Rp3.000',NULL,'24 jam',NULL,5000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6603164,110.1300437','29','Belum ada rating/ulasan di Google Maps',ST_SetSRID(ST_MakePoint(110.1300437,-7.6603164),4326));
INSERT INTO destinasi_wisata VALUES (40,'Gunung Lanang',1,'Girimulyo','Jatimulyo','Kulon Progo','Park, Tourist attraction','Gunung Lanang merupakan destinasi wisata perbukitan di Kulon Progo yang menawarkan panorama alam dari ketinggian. Kawasan ini menarik untuk menikmati pemandangan perbukitan, berfoto, dan mengenal lanskap alam setempat.',4.2,198,'Rp3.000 - Rp5.000',NULL,NULL,'08.00 – 18.00',NULL,4000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7468187,110.1404933','51','',ST_SetSRID(ST_MakePoint(110.1404933,-7.7468187),4326));
INSERT INTO destinasi_wisata VALUES (41,'Gunung pakel',1,'Samigaluh','Pagerharjo','Kulon Progo','Hiking area','Gunung Pakel merupakan tujuan wisata alam yang dapat dimanfaatkan untuk menikmati karakter lanskap perbukitan di wilayah Kulon Progo. Kawasan ini menarik bagi wisatawan yang ingin menjelajahi lingkungan alam dan menikmati suasana pedesaan.',NULL,NULL,'Rp0','Rp5.000-Rp10.000',NULL,'24 jam',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6626802,110.1320557','30','Belum ada rating/ulasan di Google Maps',ST_SetSRID(ST_MakePoint(110.1320557,-7.6626802),4326));
INSERT INTO destinasi_wisata VALUES (42,'Isis Hill',1,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction','Isis Hill merupakan destinasi perbukitan di kawasan Nglinggo yang menawarkan suasana sejuk dan panorama hijau Perbukitan Menoreh. Lokasinya cocok untuk menikmati pemandangan alam, fotografi, dan bersantai di area terbuka.',4.5,67,'Rp3.000',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',3000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6450337,110.1434925','32','Titik batas: RBI menempatkan di Salaman (selisih 112 m dari batas); mengikuti catatan tim',ST_SetSRID(ST_MakePoint(110.1434925,-7.6450337),4326));
INSERT INTO destinasi_wisata VALUES (43,'Kedung Pedut Waterfall',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction','Kedung Pedut Waterfall merupakan air terjun di kawasan Girimulyo, Kulon Progo, yang terkenal dengan aliran air jernih dan kolam alami berwarna kehijauan. Dikelilingi pepohonan dan bebatuan, tempat ini cocok untuk menikmati keindahan alam dan bermain air.',4.5,3998,'Rp10.000 - Rp20.000',NULL,NULL,'08.00 – 15.30','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',15000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7699875,110.1210707','45','',ST_SetSRID(ST_MakePoint(110.1210707,-7.7699875),4326));
INSERT INTO destinasi_wisata VALUES (44,'Kedung Sowo',1,'Samigaluh','Gerbosari','Kulon Progo','Tourist attraction','Kedung Sowo merupakan destinasi wisata alam di kawasan Gerbosari, Samigaluh. Lingkungan alami dan suasana perdesaan di sekitarnya menjadikannya tempat yang menarik untuk menikmati ketenangan alam dan menjelajahi lanskap Perbukitan Menoreh.',4.8,23,'Rp0',NULL,NULL,'07.00 – 17.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6800237,110.1662431','34','',ST_SetSRID(ST_MakePoint(110.1662431,-7.6800237),4326));
INSERT INTO destinasi_wisata VALUES (45,'KIDUL PATROL JURUGAN',1,'Kalibawang','Banjarasri','Kulon Progo','National reserve, Tourist attraction','Kidul Patrol Jurugan merupakan destinasi yang berada di kawasan pedesaan Kulon Progo dengan potensi keindahan alam dan suasana lingkungan yang asri. Tempat ini dapat menjadi pilihan bagi pengunjung yang ingin menjelajahi kawasan sekitar dan menikmati ketenangan alam.',4.2,28,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7032441,110.2340938','73','',ST_SetSRID(ST_MakePoint(110.2340938,-7.7032441),4326));
INSERT INTO destinasi_wisata VALUES (46,'Lembah Khayangan',1,'Girimulyo','Pendoworejo','Kulon Progo','Alam','Lembah Khayangan merupakan destinasi wisata alam yang menawarkan pemandangan lembah hijau dan suasana perbukitan yang menenangkan. Tempat ini cocok untuk menikmati panorama alam, berfoto, dan bersantai di lingkungan terbuka.',4.6,51,'Rp0','Rp120.000 - Rp500.000',NULL,'11.00 – 21.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7464642,110.1828333','56','',ST_SetSRID(ST_MakePoint(110.1828333,-7.7464642),4326));
INSERT INTO destinasi_wisata VALUES (47,'Nanggulan Rice Terrace, Watumurah, Pendowoharjo',1,'Girimulyo','Pendoworejo','Kulon Progo','Tourist attraction','Nanggulan Rice Terrace, Watumurah, Pendowoharjo merupakan kawasan persawahan yang menampilkan hamparan lahan pertanian dengan pola terasering dan suasana pedesaan. Lanskap hijau serta aktivitas pertanian masyarakat menjadi daya tarik bagi wisatawan yang ingin menikmati pemandangan alam.',4.3,113,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7479509,110.1903153','54','',ST_SetSRID(ST_MakePoint(110.1903153,-7.7479509),4326));
INSERT INTO destinasi_wisata VALUES (48,'PUNCAK 9 BUKIT NGISIS',1,'Samigaluh','Pagerharjo','Kulon Progo','Tourist attraction','Puncak 9 Bukit Ngisis merupakan salah satu spot sunrise di kawasan Desa Wisata Nglinggo. Dari ketinggian, pengunjung dapat menikmati panorama Perbukitan Menoreh dan sejumlah gunung di Jawa Tengah, serta memanfaatkan kawasan ini untuk berkemah dan menikmati suasana pagi.',4.6,1058,'Rp5.000–Rp10.000','Rp25.000–Rp1.600.000','Rp3.000–Rp35.000','24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',7500,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6459715,110.1432474','31','Titik batas: RBI menempatkan di Salaman (selisih 31 m dari batas); mengikuti catatan tim',ST_SetSRID(ST_MakePoint(110.1432474,-7.6459715),4326));
INSERT INTO destinasi_wisata VALUES (49,'Puncak Giri Sembung',1,'Kalibawang','Banjarasri','Kulon Progo','Tourist attraction','Puncak Giri Sembung merupakan destinasi wisata perbukitan yang menawarkan suasana alami dan panorama lanskap sekitarnya. Lokasi ini dapat menjadi pilihan untuk menikmati udara segar, bersantai, dan melihat keindahan alam Kulon Progo dari ketinggian.',4.4,57,'Rp0','Rp450.000 - Rp700.000',NULL,'08.00 – 13.00',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6917865,110.2097191','72','',ST_SetSRID(ST_MakePoint(110.2097191,-7.6917865),4326));
INSERT INTO destinasi_wisata VALUES (50,'Puncak Kleco Desa Wisata Tinalah',1,'Samigaluh','Purwoharjo','Kulon Progo','Tourist attraction','Puncak Kleco merupakan destinasi wisata alam di kawasan Perbukitan Menoreh yang menyuguhkan panorama perbukitan dan bentang alam sekitarnya dari ketinggian. Tempat ini cocok untuk menikmati pemandangan, berfoto, dan melakukan aktivitas wisata alam.',4.5,385,'Rp6.500 - Rp20.000','Rp20.000–Rp140.000','Rp8.000–Rp170.000','24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',13000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7125459,110.2045109','26','',ST_SetSRID(ST_MakePoint(110.2045109,-7.7125459),4326));
INSERT INTO destinasi_wisata VALUES (51,'Puncak Kuda Sembrani-Desa Wisata Banjarasri',1,'Kalibawang','Banjarasri','Kulon Progo','Tourist attraction','Puncak Kuda Sembrani di Desa Wisata Banjarasri merupakan destinasi wisata alam yang menyuguhkan pemandangan kawasan perbukitan Kulon Progo. Tempat ini menarik bagi pengunjung yang ingin menikmati panorama alam, menjelajahi lingkungan pedesaan, dan melakukan fotografi lanskap.',4.3,17,'Rp0','Rp105.000 - Rp200.000',NULL,'06.00 – 18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6920487,110.2131553','71','',ST_SetSRID(ST_MakePoint(110.2131553,-7.6920487),4326));
INSERT INTO destinasi_wisata VALUES (52,'Puncak Moyeng',1,'Girimulyo','Pendoworejo','Kulon Progo','Tourist attraction','Puncak Moyeng merupakan destinasi wisata alam di kawasan perbukitan Menoreh yang menawarkan pemandangan lanskap hijau dari ketinggian. Suasananya cocok untuk menikmati udara segar, fotografi alam, dan bersantai.',4.5,112,'Rp0',NULL,NULL,'24 jam',NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7505125,110.1785781','53','',ST_SetSRID(ST_MakePoint(110.1785781,-7.7505125),4326));
INSERT INTO destinasi_wisata VALUES (53,'Puncak Sigong Sunrise Spot',1,'Samigaluh','Banjarsari','Kulon Progo','National reserve','Puncak Sigong merupakan destinasi perbukitan yang dikenal sebagai tempat menikmati matahari terbit di kawasan Samigaluh. Suasana alam yang terbuka dan panorama perbukitan menjadikannya pilihan untuk menikmati pagi serta mengabadikan pemandangan dari ketinggian.',4.7,19,'Rp0',NULL,NULL,'24 Jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6856410,110.1550067','33','',ST_SetSRID(ST_MakePoint(110.1550067,-7.6856410),4326));
INSERT INTO destinasi_wisata VALUES (54,'Puncak Widosari - Desa Wisata Widosari',1,'Samigaluh','Ngargosari','Kulon Progo','Tourist attraction','Puncak Widosari di Desa Wisata Widosari merupakan destinasi wisata perbukitan yang terkenal dengan formasi batuan besar dan panorama alam Perbukitan Menoreh. Dari kawasan puncak, pengunjung dapat menikmati bentang alam yang luas serta suasana sejuk yang menarik untuk fotografi dan wisata alam.',4.6,819,'Rp15.000','Rp35.000 - Rp175.000',NULL,'06.00–18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',15000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6583125,110.1488125','58','',ST_SetSRID(ST_MakePoint(110.1488125,-7.6583125),4326));
INSERT INTO destinasi_wisata VALUES (55,'SANGKAL PUTUNG MBEJI',1,'Kalibawang','Banjaroyo','Kulon Progo','Hospital',NULL,4.6,29,NULL,NULL,NULL,NULL,NULL,2500,2,'estimasi: median kategori (data tiket belum ada)',TRUE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6488365,110.2515226','35','Harga tiket belum tercatat; diestimasi dari median kategori',ST_SetSRID(ST_MakePoint(110.2515226,-7.6488365),4326));
INSERT INTO destinasi_wisata VALUES (56,'Tompak View',1,'Girimulyo','Giripurwo','Kulon Progo','Tourist attraction','Tompak View merupakan destinasi wisata dengan panorama perbukitan dan bentang alam pedesaan Kulon Progo. Tempat ini cocok untuk menikmati pemandangan dari ketinggian, bersantai, dan mengabadikan keindahan alam.',4.3,185,'Rp0',NULL,NULL,'24 Jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7559602,110.1594015','52','',ST_SetSRID(ST_MakePoint(110.1594015,-7.7559602),4326));
INSERT INTO destinasi_wisata VALUES (57,'Watu Tekek',1,'Samigaluh','Sidoharjo','Kulon Progo','Tourist attraction','Watu Tekek merupakan destinasi wisata alam yang menawarkan suasana alami di kawasan perbukitan Kulon Progo. Tempat ini dapat menjadi pilihan untuk menikmati pemandangan alam dan ketenangan lingkungan pedesaan.',4.2,150,'Rp4.000',NULL,NULL,'06.00–18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',4000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6643486,110.2081121','37','',ST_SetSRID(ST_MakePoint(110.2081121,-7.6643486),4326));
INSERT INTO destinasi_wisata VALUES (58,'Watu Tumpang Samigaluh',1,'Samigaluh','Banjarsari','Kulon Progo','Shrine','Watu Tumpang Samigaluh merupakan destinasi wisata alam di kawasan Perbukitan Menoreh, Kulon Progo, yang menawarkan suasana pedesaan dan bentang alam perbukitan. Tempat ini cocok untuk menikmati ketenangan alam dan menjelajahi keindahan lingkungan sekitar.',4.1,11,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7020761,110.1818026','69','',ST_SetSRID(ST_MakePoint(110.1818026,-7.7020761),4326));
INSERT INTO destinasi_wisata VALUES (59,'Wisata Air Terjun Watu Jengger',1,'Samigaluh','Sidoharjo','Kulon Progo','Tourist attraction','Wisata Air Terjun Watu Jengger merupakan destinasi wisata alam yang menawarkan keindahan aliran air terjun dan suasana lingkungan yang asri. Tempat ini cocok untuk menikmati kesejukan alam dan menjelajahi keindahan lanskap pedesaan.',4.0,73,'Rp0 - Rp5.000',NULL,NULL,'07.00 – 17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',2500,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6564309,110.2070708','36','',ST_SetSRID(ST_MakePoint(110.2070708,-7.6564309),4326));
INSERT INTO destinasi_wisata VALUES (60,'Wisata Alam Kedung Banteng',1,'Girimulyo','Jatimulyo','Kulon Progo','Tourist attraction','Wisata Alam Kedung Banteng merupakan destinasi wisata alam yang menawarkan suasana lingkungan hijau dan panorama khas perbukitan Kulon Progo. Tempat ini cocok untuk menikmati ketenangan alam dan menjelajahi keindahan pedesaan.',4.3,77,'Rp0',NULL,NULL,'08.00 – 16.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7723707,110.1307018','43','',ST_SetSRID(ST_MakePoint(110.1307018,-7.7723707),4326));
INSERT INTO destinasi_wisata VALUES (61,'Wisata Punthuk Ngepoh',1,'Kalibawang','Banjararum','Kulon Progo','Tourist attraction','Wisata Punthuk Ngepoh merupakan destinasi wisata alam yang menawarkan panorama perbukitan dan pemandangan pedesaan dari ketinggian. Suasananya cocok untuk bersantai, menikmati udara segar, dan mengabadikan keindahan lanskap alam.',4.5,35,'Rp6.000',NULL,NULL,'08.00–23.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',6000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7173943,110.1918837','70','',ST_SetSRID(ST_MakePoint(110.1918837,-7.7173943),4326));
INSERT INTO destinasi_wisata VALUES (62,'Ancol Bridge - Bligo (Ancol Kalibawang)',2,'Kalibawang','Banjaroyo','Kulon Progo','Bridge, Tourist attraction','Ancol Kalibawang Kulon Progo merupakan kawasan wisata di sekitar aliran Sungai Progo yang menawarkan suasana alam dan ruang terbuka untuk rekreasi. Tempat ini dapat menjadi pilihan untuk bersantai, menikmati pemandangan sungai, dan menghabiskan waktu bersama keluarga.',4.4,1867,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6644589,110.2670825','75; 87','Gabungan 2 entri duplikat (asumsi, jarak 132 m); konfirmasi saat ground check; Titik batas: RBI menempatkan di Ngluwar (selisih 9 m dari batas); mengikuti catatan tim',ST_SetSRID(ST_MakePoint(110.2670825,-7.6644589),4326));
INSERT INTO destinasi_wisata VALUES (63,'Desa Wisata Banjarasri',2,'Kalibawang','Banjarasri','Kulon Progo','Tourist attraction','Desa Wisata Banjarasri merupakan destinasi wisata berbasis masyarakat di Kecamatan Kalibawang, Kulon Progo. Desa ini menawarkan potensi wisata alam, kehidupan pedesaan, dan aktivitas masyarakat lokal yang dapat memberikan pengalaman wisata sekaligus mengenalkan potensi wilayah setempat.',4.6,205,'Rp0',NULL,'Rp65.000–Rp200.000/orang','09.00–17.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6985187,110.2254251','25','',ST_SetSRID(ST_MakePoint(110.2254251,-7.6985187),4326));
INSERT INTO destinasi_wisata VALUES (64,'Desa Wisata Tinalah (Dewi Tinalah - Wisata Jogja)',2,'Samigaluh','Purwoharjo','Kulon Progo','Tourist attraction, National reserve, Tourist information center','Desa Wisata Tinalah menawarkan pengalaman berwisata di tengah lanskap pedesaan dan perbukitan Menoreh. Pengunjung dapat menikmati wisata alam, kegiatan luar ruang, serta aktivitas edukatif yang mengenalkan potensi dan kehidupan masyarakat setempat.',4.5,1251,'Rp10.000 - Rp20.000','Rp10.000–Rp450.000','Rp8.000–Rp170.000','08.00–16.00; Jumat tercatat memiliki jeda operasional','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',15000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6955803,110.1958839','20','',ST_SetSRID(ST_MakePoint(110.1958839,-7.6955803),4326));
INSERT INTO destinasi_wisata VALUES (65,'Embung Krapyak',2,'Kalibawang','Banjaroyo','Kulon Progo','Tourist attraction','Embung Krapyak merupakan tampungan air yang berada di lingkungan pedesaan Kulon Progo dan berfungsi mendukung kebutuhan air setempat. Kawasan sekitarnya menawarkan suasana terbuka yang cocok untuk menikmati pemandangan dan ketenangan alam.',4.3,374,'Rp0 - Rp5.000',NULL,NULL,'06.00–18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',2500,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6707898,110.2622266','88','',ST_SetSRID(ST_MakePoint(110.2622266,-7.6707898),4326));
INSERT INTO destinasi_wisata VALUES (66,'Gerbang Samudra Raksa',2,'Kalibawang','Banjaroyo','Kulon Progo','Park','Gerbang Samudra Raksa merupakan landmark wisata dan kawasan rekreasi di Banjaroya, Kalibawang, Kulon Progo. Destinasi ini berada pada jalur Nanggulan–Mendut dan dapat menjadi salah satu titik kunjungan untuk menikmati ruang terbuka sekaligus mengenal kawasan wisata di bagian barat Yogyakarta.',4.6,160,'Rp0',NULL,NULL,'Senin – Jumat: 07.00 – 20.00, Sabtu – Minggu : 07.00 – 21.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6426803,110.2540437','74','',ST_SetSRID(ST_MakePoint(110.2540437,-7.6426803),4326));
INSERT INTO destinasi_wisata VALUES (67,'Gunung Kendil',2,'Samigaluh','Sidoharjo','Kulon Progo','National reserve','Gunung Kendil merupakan destinasi wisata alam berupa perbukitan yang menawarkan pemandangan lanskap sekitarnya. Kawasan ini menarik bagi pengunjung yang ingin menikmati suasana alam, menjelajahi lingkungan perbukitan, dan mengambil foto.',4.7,444,'Rp5.000',NULL,NULL,'24 jam, waktu kunjungan terbaik: 04.00 – 09.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',5000,2,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6465812,110.1855748','79','',ST_SetSRID(ST_MakePoint(110.1855748,-7.6465812),4326));
INSERT INTO destinasi_wisata VALUES (68,'Relay Pandang TAMANAN',2,'Girimulyo','Jatimulyo','Kulon Progo','Observation deck','Gardu Pandang Tamanan merupakan tempat untuk menikmati panorama alam dari ketinggian di kawasan Kulon Progo. Lokasi ini cocok untuk bersantai, melihat bentang alam pedesaan, dan mengabadikan pemandangan sekitar.',4.5,156,'Rp0',NULL,NULL,'24 jam','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7788013,110.1130891','81','',ST_SetSRID(ST_MakePoint(110.1130891,-7.7788013),4326));
INSERT INTO destinasi_wisata VALUES (69,'Tinitah Alam',2,'Girimulyo','Pendoworejo','Kulon Progo','Tourist attraction, Indonesian restaurant','Tinitah Alam merupakan destinasi wisata yang mengangkat suasana alam dan lingkungan hijau sebagai daya tarik utama. Tempat ini dapat menjadi pilihan untuk bersantai, menikmati udara segar, dan menghabiskan waktu di kawasan pedesaan.',4.4,1041,'Rp0',NULL,'Rp3.000 - Rp37.000','Senin – Jumat: 11.00 – 20.00, Sabtu – Minggu : 09.00 – 20.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.7432698,110.1912207','78','',ST_SetSRID(ST_MakePoint(110.1912207,-7.7432698),4326));
INSERT INTO destinasi_wisata VALUES (70,'Waduk Mini Embung Banjaroya (Embung Tonogoro)',2,'Kalibawang','Banjaroyo','Kulon Progo','Tourist attraction','Embung Tonogoro di Desa Banjaroya, Kalibawang, merupakan tampungan air yang mendukung kebutuhan pengairan dan aktivitas pertanian masyarakat setempat. Lingkungan pedesaannya menawarkan suasana yang tenang serta pemandangan alam yang menarik untuk dinikmati.',4.32,1783,'Rp0','Rp120.000',NULL,'08.00 – 18.00','Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu',0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,1.0,TRUE,'https://www.google.com/maps/search/?api=1&query=-7.6588048,110.2348574','77; 84','Gabungan 2 entri duplikat (asumsi, jarak 58 m); konfirmasi saat ground check',ST_SetSRID(ST_MakePoint(110.2348574,-7.6588048),4326));
INSERT INTO destinasi_wisata VALUES (71,'DEMAJI Eco Park Purworejo',5,'Kaligesing','Kaligono','Purworejo','Tourist attraction','DEMAJI Eco Park merupakan destinasi wisata di Kabupaten Purworejo yang mengusung suasana alam dan ruang terbuka. Tempat ini dapat menjadi pilihan untuk menikmati lingkungan hijau dan menghabiskan waktu bersama keluarga atau teman.',4.3,214,'Rp3.000 - Rp15.000','Rp25.000 - Rp120.000',NULL,NULL,NULL,9000,3,'tiket masuk (nilai tengah)',FALSE,FALSE,1.5,FALSE,'https://www.google.com/maps/search/?api=1&query=-7.7322160,110.0807439','13','Di luar cakupan 3 kapanewon (Kaligesing, Purworejo)',ST_SetSRID(ST_MakePoint(110.0807439,-7.7322160),4326));
INSERT INTO destinasi_wisata VALUES (72,'Gua Maria Watu Tumpeng Kapuhan (Saint Mary''s Grotto)',3,'Borobudur','Majaksingi','Magelang','Place of worship','Gua Maria Watu Tumpeng Kapuhan merupakan tempat ziarah umat Katolik yang digunakan untuk berdoa dan melakukan refleksi spiritual. Dengan suasana yang tenang, tempat ini menjadi tujuan bagi peziarah yang ingin mendekatkan diri kepada Tuhan.',4.5,50,'Rp0',NULL,NULL,NULL,NULL,0,1,'tiket masuk (nilai tengah)',FALSE,FALSE,0.75,FALSE,'https://www.google.com/maps/search/?api=1&query=-7.6498756,110.2023839','17','Di luar cakupan 3 kapanewon (Borobudur, Magelang)',ST_SetSRID(ST_MakePoint(110.2023839,-7.6498756),4326));
